#!/bin/bash
set -e; P=/proto; G=$P/gti/depths_processed.gti; COG=$P/depths/processed_cog_c26; cd /tmp
ext() { gdalinfo "$1" | python3 -c "import sys,re; t=sys.stdin.read(); ul=re.search(r'Upper Left\s*\(\s*([-\d.]+),\s*([-\d.]+)',t); lr=re.search(r'Lower Right\s*\(\s*([-\d.]+),\s*([-\d.]+)',t); print(ul[1],lr[2],lr[1],ul[2])"; }
echo "== (a) level-10 window through GTI vs the COG tile"; E=$(ext $COG/10_17252_13419.tif); gdal_translate -q -projwin_srs EPSG:4326 -projwin $(echo $E | awk '{print $1,$4,$3,$2}') $G a.tif; gdalinfo -checksum a.tif | grep Checksum | tr '\n' ' '; echo; gdalinfo -checksum $COG/10_17252_13419.tif | grep Checksum | tr '\n' ' '; echo
echo "== (b) level-9 window at level-9 resolution through GTI vs the overview tile"; T9=$(ls $COG/overviews/9_*.tif | head -1); E=$(ext $T9); s9=$(python3 -c "print(8/2**9/960)"); gdal_translate -q -projwin_srs EPSG:4326 -projwin $(echo $E | awk '{print $1,$4,$3,$2}') -tr $s9 $s9 -r near $G b.tif; gdalinfo -checksum b.tif | grep -E 'Size is|Checksum' | tr '\n' ' '; echo; gdalinfo -checksum $T9 | grep -E 'Size is|Checksum' | tr '\n' ' '; echo "  ($(basename $T9))"
echo "== (c) POLAR: 75N (x3) and 85N (x9) tiles through GTI"; for t in 10_21888_4693 10_23168_1564; do E=$(ext $P/depths/polar_synth/$t.tif); gdal_translate -q -projwin_srs EPSG:4326 -projwin $(echo $E | awk '{print $1,$4,$3,$2}') $G p.tif; printf '  %s: ' $t; gdalinfo -stats p.tif 2>/dev/null | grep -E 'Size is|STATISTICS_(MINIMUM|MAXIMUM|VALID_PERCENT)' | tr '\n' ' ' | sed 's/  */ /g'; echo; done
echo "== (d) two native levels in ONE index"; gdaltindex -q -overwrite -f GPKG -lyr_name tiles -tr $(python3 -c "print(8/2**10/960)") $(python3 -c "print(8/2**10/960)") -ot Float64 -bandcount 2 -nodata nan -nodata nan -write_absolute_path $P/gti/mixed.gti.gpkg $COG/10_17252_13419.tif $T9; gdalinfo $P/gti/mixed.gti.gpkg | grep -E 'Size is|Pixel'; E=$(ext $COG/10_17252_13419.tif); gdal_translate -q -projwin_srs EPSG:4326 -projwin $(echo $E | awk '{print $1,$4,$3,$2}') $P/gti/mixed.gti.gpkg d.tif; gdalinfo -checksum d.tif | grep Checksum | tr '\n' ' '; echo " (expect 20175 15241 if the level-10 tile wins where both cover)"
